helpers.baseline:
float cloudCoverage(vec2 uv,float lod){
 float weight=cloudPatchWeight*(1.-smoothstep(0.,1.,lod));
 if(weight>0.){
  vec2 p=vec2(fract(uv.x-cloudPatchRegion.x),uv.y-cloudPatchRegion.y)/cloudPatchRegion.zw;
  float edge=min(min(p.x,p.y),min(1.-p.x,1.-p.y))*float(textureSize(cloudPatchMap,0).x);
  weight*=smoothstep(0.,32.,edge);
  if(weight>0.){
   float fine=texture2DLodEXT(cloudPatchMap,p,max(0.,lod+cloudPatchBias)).r;
   if(weight>=1.)return fine;
   return mix(texture2DLodEXT(cloudMap,uv,max(0.,lod)).r,fine,weight);
  }
 }
 return texture2DLodEXT(cloudMap,uv,max(0.,lod)).r;
}

helpers.branchless:
float cloudCoverage(vec2 uv,float lod){
float base=texture2DLodEXT(cloudMap,uv,max(0.,lod)).r;
if(cloudPatchWeight<=0.||lod>=1.)return base;
vec2 p=vec2(fract(uv.x-cloudPatchRegion.x),uv.y-cloudPatchRegion.y)/cloudPatchRegion.zw;
float edge=min(min(p.x,p.y),min(1.-p.x,1.-p.y))*float(textureSize(cloudPatchMap,0).x);
float weight=cloudPatchWeight*(1.-smoothstep(0.,1.,lod))*smoothstep(0.,32.,edge);
return mix(base,texture2DLodEXT(cloudPatchMap,p,max(0.,lod+cloudPatchBias)).r,weight);
}

helpers.interior:
float cloudCoverage(vec2 uv,float lod){
if(cloudPatchWeight<=0.||lod>=1.)return texture2DLodEXT(cloudMap,uv,max(0.,lod)).r;
vec2 p=vec2(fract(uv.x-cloudPatchRegion.x),uv.y-cloudPatchRegion.y)/cloudPatchRegion.zw;
float edge=min(min(p.x,p.y),min(1.-p.x,1.-p.y))*float(textureSize(cloudPatchMap,0).x);
if(cloudPatchWeight>=1.&&lod<=0.&&edge>=32.)return texture2DLodEXT(cloudPatchMap,p,max(0.,lod+cloudPatchBias)).r;
float weight=cloudPatchWeight*(1.-smoothstep(0.,1.,lod))*smoothstep(0.,32.,edge);
float base=texture2DLodEXT(cloudMap,uv,max(0.,lod)).r;
if(weight<=0.)return base;
return mix(base,texture2DLodEXT(cloudPatchMap,p,max(0.,lod+cloudPatchBias)).r,weight);
}

